{
  "references": [
    {
      "id": "R1",
      "summary_ko": "코끼리가 강에 닿지 않음"
    },
    {
      "id": "R2",
      "summary_ko": "코끼리 뒤에 흔들리는 꼬리가 두 개 있는 것처럼 보임"
    },
    {
      "id": "R3",
      "summary_ko": "코끼리의 움직임과 깜빡임이 부자연스러움"
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "코끼리 코가 비정상적으로 늘어나고 뒤틀리며 수면 위를 미끄러짐"
    },
    {
      "id": "C2",
      "summary_ko": "코끼리 앞다리 근처의 물 텍스처와 물결이 비정상적으로 리셋되고 떨림"
    },
    {
      "id": "C3",
      "summary_ko": "코끼리 코가 물에 닿는 동안 부자연스럽게 늘어나며 길이와 곡률이 빠르게 변함"
    },
    {
      "id": "C4",
      "summary_ko": "꼬리가 깜빡거리고 두께가 변하며 배경 식물과 섞임"
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "강에 닿지 않는다는 내용과 코가 늘어나며 수면 위를 미끄러진다는 설명은 결함 내용이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "대상과 결함 유형이 다릅니다 (코끼리의 강 접촉 여부 대 앞다리 주변 수면 텍스처 오류)."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "코가 강에 닿지 않는다는 설명과 물에 닿으면서 길이가 변한다는 설명은 서로 상반됩니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "대상과 결함이 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "꼬리의 이상과 코의 늘어남 현상으로 대상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "꼬리 이상과 수면 텍스처 오류로 대상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "꼬리 이상과 코의 신축 현상으로 대상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "uncertain",
      "reason_ko": "둘 다 코끼리 꼬리의 이상을 지적하지만, 꼬리가 두 개로 보인다는 설명과 꼬리의 깜빡임/두께 변화/배경 융합이 동일 결함인지 모호합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "전반적인 움직임과 눈 깜빡임에 대한 설명과 코의 변형 오류는 결함 세부 내용이 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "움직임/눈 깜빡임 이상과 수면 텍스처 이상은 대상이 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "코의 구체적 신축 현상과 전반적인 움직임/눈 깜빡임 결함은 세부 내용이 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "꼬리의 형태적/렌더링 이상과 신체 움직임/눈 깜빡임 이상은 서로 다릅니다."
    }
  ]
}
